// reads deposit amount, validates, returns amount to add
float deposit() {
    float amount = 0.0f;

    printf("\nEnter amount to deposit: $");
    scanf("%f", &amount);

    if(amount < 0) {
        printf("Invalid amount!\n");
        return 0.0f; // return 0 so balance doesn't change
    }
    else {
        printf("Successfully deposited $%.2f\n", amount);
    }

    return amount;
}

